urlset:
{% set siteUrl = "https" + "://www.awaylands.com" %}

    {{ siteUrl }}/
    {{ homepage._updatedAt }}

  {{ siteUrl }}/blog/
  {{ siteUrl }}/destinations/
  {{ siteUrl }}/about/
{% for category in categories.items %}
  {% if category.title != "* Most Popular Posts *" %}

    {{ siteUrl }}{{ category | route('category') }}/
    {{ category._updatedAt }}

  {% endif %}
{% endfor %}
{% for location in locations.items %}

    {{ siteUrl }}{{ location | route('location') }}/
    {{ location._updatedAt }}

{% endfor %}
{% for continent in continents.items %}

    {{ siteUrl }}{{ continent | route('continent') }}/
    {{ continent._updatedAt }}

{% endfor %}
{% set storyPages = [stories1.items, stories2.items, stories3.items, stories4.items] %}
{% for stories in storyPages %}
  {% for story in stories %}
  {% if story.slug or story.title %}

    {{ siteUrl }}{% if story.slug %}{{ story | route('storySlug') }}{% else %}{{ story | route('story') }}{% endif %}/
    {{ story._updatedAt }}

  {% endif %}
  {% endfor %}
{% endfor %}
